/**
 * Constants used across flow plugin implementations
 */

/**
 * Default parameter name for flow arrow functions when none can be extracted
 */
export const DEFAULT_PARAM_NAME = '_params'

/**
 * Default flow priority level
 */
export const FLOW_PRIORITY_DEFAULT = 'MEDIUM'

/**
 * Default user context for flow execution
 */
export const RUN_AS_DEFAULT = 'system'

/**
 * Default access level for flows
 */
export const ACCESS_DEFAULT = 'public'

/**
 * Source identifier for Fluent-generated flows
 */
export const GENERATION_SOURCE = 'fluent'

/**
 * Separator used in parallel instance ordering (e.g., "1➛2")
 */
export const PARALLEL_ORDER_SEPARATOR = '➛'

/**
 * Default empty string value
 */
export const EMPTY_STRING = ''

/**
 * Default boolean string values
 */
export const BOOLEAN_FALSE_STRING = 'false'
export const BOOLEAN_TRUE_STRING = 'true'

/**
 * Flow status constants
 */
export const FLOW_STATUS_DRAFT = 'draft'

/**
 * Flow version for Fluent flows
 */
export const FLOW_VERSION = '2'

/**
 * Flow types
 */
export const FLOW_TYPE_FLOW = 'flow'
export const FLOW_TYPE_SUBFLOW = 'subflow'

/**
 * Display value maps for trigger input transformations
 * Used to convert internal values to user-friendly display values
 */

/**
 * Day of week value to display name mapping
 * Maps numeric day values (1-7) to their string representations
 */
export const DAY_OF_WEEK_DISPLAY_MAP: Record<string, string> = {
    '1': 'Monday',
    '2': 'Tuesday',
    '3': 'Wednesday',
    '4': 'Thursday',
    '5': 'Friday',
    '6': 'Saturday',
    '7': 'Sunday',
}
